{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket public access block missing 'block_public_acls'",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "HIGH",
      "explanation": "The 'block_public_acls' attribute is not set, which means public ACLs could still be applied to the bucket. This increases the risk of unintentional public exposure of sensitive data."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n  block_public_acls       = true\n}",
  "fix_summary": "Added the 'block_public_acls' attribute to the aws_s3_bucket_public_access_block resource to ensure public ACLs cannot be applied to the bucket."
}
